### 3. `styles.css`
```css
/* CSS Reset & Variable Definitions */
:root {
    --bg-color: #000000;
    --text-color: #ffffff;
    --text-muted: #8e8e93;
    --border-color: rgba(255, 255, 255, 0.25);
    --border-color-muted: rgba(255, 255, 255, 0.1);
    --font-primary: ''Inter'', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

body {
    background-color: var(--bg-color);
    color: var(--text-color);
    font-family: var(--font-primary);
    overflow-x: hidden;
    min-height: 100vh;
}

/* Base Container */
.container {
    width: 100%;
    min-height: 100vh;
    padding: 0 60px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    position: relative;
}

/* --- HEADER NAVIGATION --- */
.header {
    height: 100px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-bottom: 1px solid rgba(255, 255, 255, 0.03);
    position: relative;
    z-index: 10;
}

/* Logo */
.logo-container {
    display: flex;
    align-items: center;
    gap: 12px;
    cursor: pointer;
}

.hamburger-icon {
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    width: 20px;
    height: 10px;
}

.hamburger-icon span {
    display: block;
    height: 2px;
    width: 100%;
    background-color: var(--text-color);
    transition: width 0.3s ease;
}

.hamburger-icon:hover span:nth-child(2) {
    width: 70%;
}

.logo-text {
    font-size: 18px;
    font-weight: 900;
    letter-spacing: -0.02em;
    text-transform: uppercase;
    display: flex;
    align-items: flex-start;
}

.copyright-symbol {
    font-size: 10px;
    font-weight: 500;
    margin-left: 2px;
    position: relative;
    top: -1px;
}

/* Nav Links */
.nav-links {
    display: flex;
    align-items: center;
    gap: 40px;
    margin-left: auto;
    margin-right: 50px;
}

.nav-link {
    color: var(--text-color);
    text-decoration: none;
    font-size: 14px;
    font-weight: 500;
    opacity: 0.85;
    transition: opacity 0.25s ease, transform 0.25s ease;
    display: flex;
    align-items: flex-start;
    position: relative;
}

.nav-link:hover {
    opacity: 1;
}

.nav-badge {
    font-size: 9px;
    font-weight: 600;
    margin-left: 4px;
    opacity: 0.6;
    position: relative;
    top: -3px;
}

/* Action Buttons (Right) */
.header-actions {
    display: flex;
    align-items: center;
    gap: 12px;
}

.btn-outline {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 10px 24px;
    border: 1px solid var(--border-color);
    border-radius: 9999px;
    color: var(--text-color);
    text-decoration: none;
    font-size: 14px;
    font-weight: 500;
    transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
    background-color: transparent;
}

.btn-outline .plus-sign {
    margin-right: 4px;
    font-weight: 400;
}

.btn-outline:hover {
    background-color: var(--text-color);
    color: var(--bg-color);
    border-color: var(--text-color);
    transform: translateY(-1px);
}

.btn-outline:active {
    transform: translateY(0);
}

/* --- HERO SECTION --- */
.hero {
    height: calc(100vh - 100px);
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    padding-bottom: 80px;
    gap: 40px;
    background-image: url(''https://res.cloudinary.com/z2uss7l7/image/upload/v1786040026/ChatGPT_Image_Aug_6_2026_11_43_29_PM_mtjexa.png'');
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
}

/* Hero Left Column */
.hero-left {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    flex: 1;
}

/* Ratings Block */
.ratings-block {
    display: flex;
    align-items: center;
    gap: 20px;
    margin-bottom: 24px;
}

.avatars-group {
    display: flex;
    align-items: center;
}

.avatar {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    border: 2.5px solid var(--bg-color);
    object-fit: cover;
}

.avatar:not(:first-child) {
    margin-left: -12px;
}

.ratings-info {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.stars-line {
    display: flex;
    align-items: center;
    gap: 8px;
}

.stars {
    color: var(--text-color);
    font-size: 8px;
    letter-spacing: 2px;
}

.rating-value {
    font-size: 12px;
    font-weight: 700;
    letter-spacing: -0.01em;
}

.reviews-count {
    font-size: 9px;
    font-weight: 700;
    color: var(--text-muted);
    letter-spacing: 0.08em;
}

/* Big Title */
.hero-title {
    font-family: ''Archivo'', sans-serif;
    font-size: clamp(4.5rem, 8.5vw, 8.5rem);
    font-weight: 900;
    line-height: 0.82;
    letter-spacing: -0.055em;
    text-transform: uppercase;
    margin-bottom: 45px;
    user-select: none;
}

/* Start Project Button */
.action-container {
    width: 100%;
}

.btn-start-project {
    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    width: 360px;
    height: 64px;
    padding: 0 28px;
    background-color: #0b0b0c;
    border: 1px solid var(--border-color-muted);
    border-radius: 6px;
    color: var(--text-color);
    text-decoration: none;
    transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.btn-start-project .btn-text {
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.1em;
}

.btn-start-project .btn-arrow {
    display: flex;
    align-items: center;
    justify-content: center;
    transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.btn-start-project:hover {
    background-color: #121214;
    border-color: rgba(255, 255, 255, 0.2);
}

.btn-start-project:hover .btn-arrow {
    transform: translateX(4px);
}

/* Hero Right Column */
.hero-right {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    justify-content: flex-end;
    width: 380px;
    min-height: 280px; /* Aligns description text vertically */
}

.hero-description {
    font-size: 20px;
    font-weight: 400;
    line-height: 1.45;
    color: var(--text-color);
    text-align: left;
    width: 100%;
    margin-bottom: 70px;
    letter-spacing: -0.01em;
}

/* Footer Logos Row */
.footer-logos {
    display: flex;
    align-items: center;
    justify-content: flex-start;
    gap: 32px;
    width: 100%;
}

.brand-item {
    display: flex;
    align-items: center;
    gap: 8px;
    color: var(--text-color);
    opacity: 0.9;
}

.brand-icon {
    opacity: 0.85;
}

.brand-name {
    font-size: 14px;
    font-weight: 500;
    letter-spacing: -0.01em;
}


/* --- SECTION GENERAL STYLES --- */
.section {
    padding: 120px 0;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.section-header {
    display: flex;
    align-items: baseline;
    gap: 12px;
    margin-bottom: 60px;
}

.section-number {
    font-size: 14px;
    font-weight: 600;
    color: var(--text-muted);
}

.section-title {
    font-size: 24px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--text-color);
}

/* --- PORTFOLIO SECTION --- */
.portfolio-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 40px;
}

.portfolio-item {
    display: flex;
    flex-direction: column;
    text-decoration: none;
    color: inherit;
    cursor: pointer;
}

.project-image-wrapper {
    position: relative;
    width: 100%;
    aspect-ratio: 4 / 3;
    overflow: hidden;
    border-radius: 6px;
    background-color: #0b0b0c;
    border: 1px solid var(--border-color-muted);
}

.project-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}

.portfolio-item:hover .project-image {
    transform: scale(1.05);
}

.project-info {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-top: 20px;
}

.project-details {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.project-title {
    font-size: 16px;
    font-weight: 700;
    letter-spacing: -0.01em;
    color: var(--text-color);
}

.project-category {
    font-size: 13px;
    font-weight: 400;
    color: var(--text-muted);
}

.project-year {
    font-size: 14px;
    font-weight: 500;
    opacity: 0.8;
}

/* --- SERVICES SECTION --- */
.services-list {
    display: flex;
    flex-direction: column;
    width: 100%;
}

.service-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 40px 24px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
    cursor: pointer;
    margin-left: -24px;
    margin-right: -24px;
    border-radius: 4px;
}

.service-index {
    font-size: 14px;
    font-weight: 600;
    color: var(--text-muted);
    width: 80px;
}

.service-name {
    font-size: 22px;
    font-weight: 800;
    width: 300px;
    letter-spacing: -0.02em;
    color: var(--text-color);
}

.service-desc {
    font-size: 15px;
    line-height: 1.5;
    color: var(--text-muted);
    flex: 1;
    max-width: 500px;
    padding-right: 40px;
}

.service-arrow {
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--text-color);
    transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.service-row:hover {
    background-color: rgba(255, 255, 255, 0.02);
    padding-left: 36px;
}

.service-row:hover .service-arrow {
    transform: translateX(8px);
}

/* --- ABOUT SECTION --- */
.about-content {
    display: grid;
    grid-template-columns: 1.2fr 1fr;
    gap: 80px;
    margin-top: 20px;
}

.about-headline {
    font-size: clamp(2rem, 3.2vw, 3rem);
    font-weight: 500;
    line-height: 1.25;
    letter-spacing: -0.035em;
    color: var(--text-color);
}

.about-right {
    display: flex;
    flex-direction: column;
}

.about-text {
    font-size: 18px;
    line-height: 1.6;
    color: var(--text-muted);
    margin-bottom: 60px;
}

.about-metrics {
    display: flex;
    justify-content: space-between;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    padding-top: 40px;
}

.metric-item {
    display: flex;
    flex-direction: column;
}

.metric-value {
    font-size: 40px;
    font-weight: 800;
    letter-spacing: -0.02em;
    color: var(--text-color);
}

.metric-label {
    font-size: 11px;
    font-weight: 600;
    color: var(--text-muted);
    text-transform: uppercase;
    margin-top: 6px;
    letter-spacing: 0.08em;
}

/* --- CONTACT & FOOTER SECTION --- */
.contact-section {
    padding: 160px 0 60px 0;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    display: flex;
    flex-direction: column;
}

.contact-cta {
    margin-bottom: 120px;
}

.contact-cta-link {
    text-decoration: none;
    color: var(--text-color);
    display: inline-flex;
    flex-direction: column;
    gap: 20px;
}

.cta-subtitle {
    font-size: 12px;
    font-weight: 700;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.12em;
}

.cta-title {
    font-family: ''Archivo'', sans-serif;
    font-size: clamp(3rem, 6vw, 5.8rem);
    font-weight: 900;
    letter-spacing: -0.045em;
    text-transform: uppercase;
    display: flex;
    align-items: center;
    gap: 24px;
    line-height: 1;
}

.cta-arrow {
    display: flex;
    align-items: center;
    transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}

.contact-cta-link:hover .cta-arrow {
    transform: translateX(16px);
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr;
    gap: 60px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    padding-bottom: 80px;
    width: 100%;
}

.footer-col {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.footer-col-title {
    font-size: 11px;
    font-weight: 700;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 10px;
}

.footer-link {
    color: var(--text-color);
    text-decoration: none;
    font-size: 15px;
    font-weight: 400;
    opacity: 0.75;
    transition: opacity 0.25s ease;
    width: fit-content;
}

.footer-link:hover {
    opacity: 1;
}

.footer-info-text {
    font-size: 15px;
    color: var(--text-color);
    opacity: 0.75;
    line-height: 1.4;
}

.footer-social-links {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.footer-bottom {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: 40px;
    font-size: 13px;
    color: var(--text-muted);
}

.footer-bottom-links {
    display: flex;
    gap: 32px;
}

.footer-bottom-link {
    color: var(--text-muted);
    text-decoration: none;
    transition: color 0.25s ease;
}

.footer-bottom-link:hover {
    color: var(--text-color);
}

/* --- RESPONSIVE STYLES --- */
@media (max-width: 1024px) {
    .container {
        padding: 0 40px;
    }
    
    .nav-links {
        gap: 24px;
        margin-right: 30px;
    }
    
    .hero {
        flex-direction: column;
        align-items: flex-start;
        justify-content: flex-start;
        padding-top: 40px;
        padding-bottom: 60px;
        gap: 60px;
        height: auto;
    }
    
    .hero-right {
        width: 100%;
        align-items: flex-start;
        min-height: auto;
    }
    
    .hero-description {
        max-width: 500px;
        margin-bottom: 40px;
    }
    
    .footer-logos {
        justify-content: flex-start;
    }

    /* 1024px Section Overrides */
    .portfolio-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 30px;
    }

    .about-content {
        grid-template-columns: 1fr;
        gap: 50px;
    }

    .footer-grid {
        grid-template-columns: 1fr 1fr 1fr;
        gap: 40px;
    }
}

@media (max-width: 768px) {
    .container {
        padding: 0 24px;
    }
    
    .header {
        height: 80px;
    }
    
    .nav-links {
        display: none; /* Hide default nav for mobile view */
    }
    
    .hero-title {
        font-size: clamp(3.5rem, 12vw, 5.5rem);
    }
    
    .btn-start-project {
        width: 100%;
        max-width: 360px;
    }
    
    .footer-logos {
        flex-wrap: wrap;
        gap: 24px;
    }

    /* 768px Section Overrides */
    .section {
        padding: 80px 0;
    }

    .portfolio-grid {
        grid-template-columns: 1fr;
        gap: 40px;
    }

    .service-row {
        flex-direction: column;
        align-items: flex-start;
        gap: 12px;
        padding: 30px 16px;
        margin-left: -16px;
        margin-right: -16px;
    }

    .service-row:hover {
        padding-left: 24px;
    }

    .service-index {
        width: auto;
    }

    .service-name {
        width: 100%;
        font-size: 18px;
    }

    .service-desc {
        max-width: 100%;
        padding-right: 0;
    }

    .service-arrow {
        display: none;
    }

    .about-headline {
        font-size: 24px;
    }

    .about-text {
        font-size: 16px;
        margin-bottom: 40px;
    }

    .about-metrics {
        flex-direction: column;
        gap: 24px;
    }

    .contact-cta-link .cta-title {
        font-size: 2.2rem;
    }

    .cta-arrow svg {
        width: 24px;
        height: 24px;
    }

    .footer-grid {
        grid-template-columns: 1fr;
        gap: 40px;
        padding-bottom: 60px;
    }

    .footer-bottom {
        flex-direction: column;
        align-items: flex-start;
        gap: 20px;
    }
}
